artifactDeck = getObjectFromGUID("9d9d6e")
curseDeck = getObjectFromGUID("e00063")
descentBag = getObjectFromGUID("68398e")
discoveryBag = getObjectFromGUID("1df169")
scenarioBox = getObjectFromGUID("6730a1")
depth1Deck = getObjectFromGUID("6ec100")
depth2Deck = getObjectFromGUID("818c76")
depth3Deck = getObjectFromGUID("d586ba")
depth4Deck = getObjectFromGUID("cf8a8e")
depth5Deck = getObjectFromGUID("344a00")
depth1Positions = { Vector({ -17.04, 2, 7.65 }), Vector({ -17.04, 2, 0 }), Vector({ -17.04, 2, -7.65 }) }
depth2Positions = { Vector({ -23.64, 2, 7.65 }), Vector({ -23.64, 2, 0 }), Vector({ -23.64, 2, -7.65 }) }
depth3Positions = { Vector({ -30.24, 2, 7.65 }), Vector({ -30.24, 2, 0 }), Vector({ -30.24, 2, -7.65 }) }
depth4Positions = { Vector({ -36.84, 2, 7.65 }), Vector({ -36.84, 2, 0 }), Vector({ -36.84, 2, -7.65 }) }
depth5Positions = { Vector({ -43.44, 2, 7.65 }), Vector({ -43.44, 2, 0 }), Vector({ -43.44, 2, -7.65 }) }
depth1UnderPositions = { Vector({ -19.34, 2.5, 7.65 }), Vector({ -19.34, 2.5, 0 }), Vector({ -19.34, 2.5, -7.65 }) }
depth2UnderPositions = { Vector({ -25.94, 2.5, 7.65 }), Vector({ -25.94, 2.5, 0 }), Vector({ -25.94, 2.5, -7.65 }) }
depth3UnderPositions = { Vector({ -32.54, 2.5, 7.65 }), Vector({ -32.54, 2.5, 0 }), Vector({ -32.54, 2.5, -7.65 }) }

function onLoad()
  self.createButton({
    label          = "Set Up",
    click_function = "setup",
    function_owner = self,
    position       = { 0, 0.11, 0 },
    height         = 120,
    width          = 500,
    scale          = { x = 1.75, y = 1.75, z = 1.75 },
    font_size      = 90
  })
end

function setup()
  if SETUP_DONE then return end
  SETUP_DONE = true

  artifactDeck.shuffle()
  curseDeck.shuffle()
  descentBag.shuffle()
  discoveryBag.shuffle()
  depth1Deck.shuffle()
  depth2Deck.shuffle()
  depth3Deck.shuffle()
  depth4Deck.shuffle()
  depth5Deck.shuffle()

    for i, pos in ipairs(depth1Positions) do
      depth1Deck.takeObject({
        position = pos,
        smooth   = false
      })
    end

    for i, pos in ipairs(depth2Positions) do
      depth2Deck.takeObject({
        position = pos,
        smooth   = false
      })
    end

    for i, pos in ipairs(depth3Positions) do
      depth3Deck.takeObject({
        position = pos,
        smooth   = false
      })
    end

    for i, pos in ipairs(depth4Positions) do
      depth4Deck.takeObject({
        position = pos,
        smooth   = false
      })
    end

    for i, pos in ipairs(depth5Positions) do
      depth5Deck.takeObject({
        position = pos,
        smooth   = false
      })
    end

    placeUnder(depth1UnderPositions)
    placeUnder(depth2UnderPositions)
    placeUnder(depth3UnderPositions)
end

function placeUnder(positions)
  local card1 = descentBag.takeObject({
    position = scenarioBox.getPosition() + Vector(0, 2, 0),
    smooth = false,
  })
  scenarioBox.putObject(card1)

  local card2 = discoveryBag.takeObject({
    position = scenarioBox.getPosition() + Vector(0, 2, 0),
    smooth = false,
  })
  scenarioBox.putObject(card2)

  local card3 = discoveryBag.takeObject({
    position = scenarioBox.getPosition() + Vector(0, 2, 0),
    smooth = false,
  })
  scenarioBox.putObject(card3)

  scenarioBox.shuffle()

    for i, pos in ipairs(positions) do
      scenarioBox.takeObject({
        position = pos,
        rotation = { 180, 0, 0 },
        smooth   = false
      })
    end
end
